LETTERS = {"2": "abc", "3": "def", "4": "ghi", "5": "jkl",
           "6": "mno", "7": "pqrs", "8": "tuv", "9": "wxyz"}


def keypad_words(digits: str) -> list[str]:
    if not digits:
        return []                        # no digit, no word: not [""]
    res, path = [], []

    def bt(i: int) -> None:
        if i == len(digits):
            res.append("".join(path))
            return
        for ch in LETTERS[digits[i]]:
            path.append(ch)              # choose
            bt(i + 1)                    # explore the next digit
            path.pop()                   # unchoose

    bt(0)
    return res
